import logging
import httpx
from tenacity import (retry, retry_if_exception, stop_after_attempt,
                      wait_exponential)

log = logging.getLogger("triage")

def is_retryable(e: BaseException) -> bool:
    """Retry network errors, rate limits and server errors; never 400/401/404."""
    if isinstance(e, httpx.TransportError):          # timeouts, dropped connections
        return True
    return (isinstance(e, httpx.HTTPStatusError)
            and e.response.status_code in (429, 500, 502, 503, 504))

@retry(retry=retry_if_exception(is_retryable),
       stop=stop_after_attempt(3),                      # 3 attempts = up to 2 retries
       wait=wait_exponential(multiplier=0.5, max=8),    # waits 0.5s, then 1s
       reraise=True)
def get_policy(policy_id: str) -> dict:
    r = httpx.get(f"https://policy.internal/api/policies/{policy_id}", timeout=5.0)
    r.raise_for_status()
    return r.json()

def check_claim(claim: dict) -> list[str]:
    """Return a list of data-quality problems (empty list = OK)."""
    problems = []
    if not claim.get("vehicle_reg"):
        problems.append("missing vehicle_reg")
    if claim.get("estimated_cost", 0) < 0:
        problems.append("negative estimated_cost")
    if problems:
        log.warning("dq_fail", extra={"claim_id": claim["id"], "problems": problems})
    return problems
